CONSENT_MODAL_CSS:'.ensCenter {\n    text-align: center;\n}\n#ensModalWrapper {\n    border: 1px solid #333;\n    position: fixed;\n    max-width: 60%;\n    border: 1px solid #000;\n    display: none;\n    box-shadow: 5px 5px 5px grey;\n    background-color: #fff;\n    padding: 20px 0;\n    z-index: 9999;\n}\n.ensModal {\n    font-family: Roboto, "Helvetica Neue", Helvetica, Arial;\n    min-width: 400px;\n    max-width: 400px;\n}\n.ensModal input[type\x3d"checkbox"] {\n    display: none;\n}\n.ensModal input[type\x3d"checkbox"]:checked ~ .toggle {\n    background: #fff;\n    left: 36px;\n    transition: 0.5s;\n}\n.ensModal input[type\x3d"checkbox"]:checked ~ .switch {\n    background: #1E6BD6;\n    transition: 0.5s;\n}\n\n.ensModal .switch {\n    display: block;\n    width: 50px;\n    height: 15px;\n    background: #939393;\n    border-radius: 10px;\n    position: absolute;\n    top: 0;\n    transition: 0.5s;\n}\n\n.ensModal .toggle {\n    height: 17px;\n    width: 17px;\n    border-radius: 50%;\n    background: white;\n    position: absolute;\n    top: -2px;\n    left: -2px;\n    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.4);\n    transition: 0.5s;\n}\n\n.ensModal .card {\n    display: inline-block;\n    margin: 9px;\n    margin: 5px;\n    width: 50px;\n    height: 20px;\n    text-align: center;\n    position: relative;\n    float: right;\n}\n\n.ensModal {\n    font-size: 18px;\n    color: #333;\n    padding: 20px 20px 0px 20px;\n}\n.ensToggleRow {\n    margin-bottom: 10px;\n}\n.ensToggleLabel {\n    margin-right: 5px;\n}\n.ensButtons {\n    clear: both;\n    margin-top: 15px;\n    float: right;\n}\n.ensButtons .button {\n    display: inline-block;\n    position: relative;\n    width: 120px;\n    height: 32px;\n    border-radius: 2px;\n    font-size: 0.9em;\n    background-color: #fff;\n    color: #646464;\n    margin-left: 20px;\n}\n.ensButtons .button.grey {\n    background-color: #eee;\n}\n.ensButtons .button.blue {\n    background-color: #2b5cac;\n    color: #fff;\n}\n\n.ensButtons .button.raised {\n    transition: box-shadow 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n    transition-delay: 0.2s;\n    box-shadow: 0 2px 5px 0 rgba(0, 0, 0, 0.26);\n}\n\n.ensButtons .button.raised:active {\n    box-shadow: 0 8px 17px 0 rgba(0, 0, 0, 0.2);\n    transition-delay: 0s;\n}\n\n.ensModal .ensTitle {\n    margin: 5px;\n    width: 95%;\n    color: #74736f;\n    position: absolute;\n    top: -5px;\n    left: -5px;\n    padding-left: 5%;\n    padding-top: 13px;\n    padding-bottom: 3px;\n    text-align: center;\n}\n\n.ensModal .consentDescription {\n    color: #333;\n    font-size: 14px;\n}\n\n.ensModal hr {\n    color: #c5c5c5;\n}\n\n.ensModal .description {\n    max-width: 600px;\n    font-size: 12px;\n    margin-top: 15px;\n    clear: both;\n}\n\n.mdl-shadow--2dp {\n    box-shadow: 0 2px 2px 0 rgba(0, 0, 0, 0.14),\n        0 3px 1px -2px rgba(0, 0, 0, 0.2), 0 1px 5px 0 rgba(0, 0, 0, 0.12);\n}\n\n.mdl-data-table {\n    position: relative;\n    border: 1px solid rgba(0, 0, 0, 0.12);\n    border-collapse: collapse;\n    white-space: nowrap;\n    font-size: 13px;\n    background-color: #fff;\n}\n\n.mdl-data-table thead {\n    padding-bottom: 3px;\n}\n\ntr {\n    display: table-row;\n    vertical-align: inherit;\n    border-color: inherit;\n}\n\n.mdl-data-table td:first-of-type,\n.mdl-data-table th:first-of-type {\n    padding-left: 24px;\n}\n\n.mdl-data-table__cell--non-numeric.mdl-data-table__cell--non-numeric {\n    text-align: left;\n}\n\ntbody {\n    display: table-row-group;\n    vertical-align: middle;\n    border-color: inherit;\n}\n\n.mdl-data-table tbody tr {\n    position: relative;\n    height: 48px;\n    transition-duration: 0.28s;\n    transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);\n    transition-property: background-color;\n}\n\n.mdl-data-table td:first-of-type,\n.mdl-data-table th:first-of-type {\n    padding-left: 24px;\n}\n\n.mdl-data-table td,\n.mdl-data-table td .mdl-data-table__select {\n    vertical-align: middle;\n}\n\n.mdl-data-table td {\n    position: relative;\n    height: 48px;\n    border-top: 1px solid rgba(0, 0, 0, 0.12);\n    border-bottom: 1px solid rgba(0, 0, 0, 0.12);\n    padding: 12px 18px;\n    box-sizing: border-box;\n}\n\n.mdl-data-table th {\n    position: relative;\n    vertical-align: bottom;\n    text-overflow: ellipsis;\n    font-weight: 700;\n    line-height: 24px;\n    letter-spacing: 0;\n    height: 48px;\n    font-size: 12px;\n    color: rgba(0, 0, 0, 0.54);\n    padding-bottom: 8px;\n    box-sizing: border-box;\n}\n\n.mdl-data-table th {\n    padding: 0 18px 12px 18px;\n    text-align: right;\n}\n\n.mdl-navigation__link {\n    color: #424242;\n    margin: 0;\n    font-size: 14px;\n    font-weight: 400;\n    line-height: 24px;\n    letter-spacing: 0;\n    opacity: 0.87;\n}\n',
